using ClosedXML.Excel;

class Program {
    static List<string> GetEcuAliases(string rawName) {
        var list = new List<string>();
        if (string.IsNullOrWhiteSpace(rawName)) return list;
        string name = rawName.Trim().ToUpperInvariant();
        list.Add(name);

        if (name == "ACU" || name == "ACM") {
            if (!list.Contains("ACU")) list.Add("ACU");
            if (!list.Contains("ACM")) list.Add("ACM");
        }
        if (name.StartsWith("BCM")) {
            if (!list.Contains("BCM")) list.Add("BCM");
            if (!list.Contains("BCM_FL")) list.Add("BCM_FL");
            if (!list.Contains("BCM_FR")) list.Add("BCM_FR");
            if (!list.Contains("BCM_BPM")) list.Add("BCM_BPM");
        }
        if (name.Contains("MCU") || name.StartsWith("EDS")) {
            if (!list.Contains("FMCU")) list.Add("FMCU");
            if (!list.Contains("RMCU")) list.Add("RMCU");
            if (!list.Contains("MCU")) list.Add("MCU");
            if (!list.Contains("EDS")) list.Add("EDS");
        }
        if (name.StartsWith("EPS")) {
            if (!list.Contains("EPS")) list.Add("EPS");
            if (!list.Contains("EPS1")) list.Add("EPS1");
            if (!list.Contains("EPS2")) list.Add("EPS2");
        }
        if (name == "IDB" || name == "ESC" || name == "ABS") {
            if (!list.Contains("IDB")) list.Add("IDB");
            if (!list.Contains("ESC")) list.Add("ESC");
            if (!list.Contains("ABS")) list.Add("ABS");
        }
        return list;
    }

    static string NormalizeDtcCodeText(string value) {
        string text = Regex.Replace(value ?? "", @"\s+", "").ToUpperInvariant();
        if (text.StartsWith("0X")) text = text.Substring(2);
        return text.Replace("-", "");
    }

    static bool IsHexText(string value) {
        if (string.IsNullOrEmpty(value)) return false;
        foreach (char ch in value) {
            bool isHex = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'F');
            if (!isHex) return false;
        }
        return true;
    }

    static bool TryJ2012ToRawHex(string dtcCode, out string rawHex) {
        rawHex = "";
        string text = NormalizeDtcCodeText(dtcCode);
        if (text.Length == 7 && "PCBU".IndexOf(text[0]) >= 0 && IsHexText(text.Substring(1))) {
            int letterIndex = "PCBU".IndexOf(text[0]);
            int d1 = Convert.ToInt32(text.Substring(1, 1), 16) & 0x03;
            int d2 = Convert.ToInt32(text.Substring(2, 1), 16) & 0x0F;
            int b1 = (letterIndex << 6) | (d1 << 4) | d2;
            rawHex = string.Format("{0:X2}{1}", b1, text.Substring(3, 4));
            return true;
        }
        if (text.Length == 6 && IsHexText(text)) {
            rawHex = text;
            return true;
        }
        return false;
    }

    static List<string> GetDtcKeyCandidates(string dtcCode) {
        var candidates = new List<string>();
        void Add(string key) {
            if (!string.IsNullOrEmpty(key) && !candidates.Contains(key))
                candidates.Add(key);
        }

        string normalized = NormalizeDtcCodeText(dtcCode);
        Add(normalized);

        string rawHex;
        if (TryJ2012ToRawHex(normalized, out rawHex))
            Add(rawHex);

        if (normalized.Length > 2) {
            string baseCode = normalized.Substring(0, normalized.Length - 2);
            Add(baseCode);
            Add(baseCode + "00");
        }

        if (!string.IsNullOrEmpty(rawHex) && rawHex.Length > 2) {
            string baseHex = rawHex.Substring(0, rawHex.Length - 2);
            Add(baseHex);
            Add(baseHex + "00");
        }

        return candidates;
    }

    static void Main() {
        string[] testCodes = {
            "U1102-87", "U1114-87", "U1118-87", "U1170-00", "U1126-87",
            "U1134-87", "U1142-87", "U1150-87", "U1152-82", "U1153-83",
            "U1186-87", "U1162-87", "U1166-87", "U1178-87", "U1182-87"
        };

        // Load VF8-9_ACM dictionary
        string path = @"TreeViews and Value Converters\bin\Debug\General\DTC\VF9\VF8-9_ACM_ODX_v2.17_edit.xlsx";
        var dict = new Dictionary<string, string>();
        using (var wb = new XLWorkbook(path)) {
            var ws = wb.Worksheets.Worksheet(1);
            int lastRow = ws.LastRowUsed().RowNumber();
            for (int r = 2; r <= lastRow; r++) {
                string dtcNum = ws.Cell(r, 3).GetString();
                string dtcHex = ws.Cell(r, 2).GetString();
                string name = ws.Cell(r, 5).GetString();
                if (!string.IsNullOrWhiteSpace(name)) {
                    foreach (var key in GetDtcKeyCandidates(dtcNum)) dict[key] = name;
                    foreach (var key in GetDtcKeyCandidates(dtcHex)) dict[key] = name;
                }
            }
        }

        Console.WriteLine("Loaded keys in dict: " + dict.Count);
        foreach (var code in testCodes) {
            string found = null;
            foreach (var key in GetDtcKeyCandidates(code)) {
                if (dict.TryGetValue(key, out found)) break;
            }
            Console.WriteLine(string.Format("{0,-10} -> {1}", code, (found ?? "[NOT FOUND]")));
        }
    }
}

