private static System.Collections.Generic.List<string> GetEcuAliases(string rawName)
{
    var aliases = new System.Collections.Generic.List<string>();
    if (string.IsNullOrWhiteSpace(rawName)) return aliases;

    void Add(string a)
    {
        if (!string.IsNullOrEmpty(a) && !aliases.Contains(a, StringComparer.OrdinalIgnoreCase))
            aliases.Add(a);
    }

    string norm = Regex.Replace(rawName, @"[^\w]", "").Trim();
    Add(norm);

    // Bóc tách tiền tố trước dấu gạch dưới / gạch ngang (VD: BCM_FL -> BCM, CR_F -> CR)
    if (norm.Contains("_"))
    {
        string prefix = norm.Split('_')[0];
        Add(prefix);
    }
    if (norm.Contains("-"))
    {
        string prefix = norm.Split('-')[0];
        Add(prefix);
    }

    // ACU <-> ACM
    if (norm.Equals("ACU", StringComparison.OrdinalIgnoreCase)) Add("ACM");
    else if (norm.Equals("ACM", StringComparison.OrdinalIgnoreCase)) Add("ACU");

    // BCM_FL, BCM_FR, BCM_RL, BCM_RR <-> BCM
    if (norm.StartsWith("BCM", StringComparison.OrdinalIgnoreCase))
    {
        Add("BCM");
        if (norm.Contains("FL")) { Add("BCM_FL"); Add("BCM-FL"); }
        if (norm.Contains("FR")) { Add("BCM_FR"); Add("BCM-FR"); }
        if (norm.Contains("RL")) { Add("BCM_RL"); Add("BCM-RL"); }
        if (norm.Contains("RR")) { Add("BCM_RR"); Add("BCM-RR"); }
    }

    // ESC <-> ESP / EBS
    if (norm.Equals("ESC", StringComparison.OrdinalIgnoreCase)) { Add("ESP"); Add("EBS"); }
    else if (norm.Equals("ESP", StringComparison.OrdinalIgnoreCase) || norm.Equals("EBS", StringComparison.OrdinalIgnoreCase)) { Add("ESC"); }

    // EPS <-> EPAS
    if (norm.Equals("EPS", StringComparison.OrdinalIgnoreCase)) Add("EPAS");
    else if (norm.Equals("EPAS", StringComparison.OrdinalIgnoreCase)) Add("EPS");

    // VCU <-> VCM
    if (norm.Equals("VCU", StringComparison.OrdinalIgnoreCase)) Add("VCM");
    else if (norm.Equals("VCM", StringComparison.OrdinalIgnoreCase)) Add("VCU");

    // GW <-> CGW
    if (norm.Equals("GW", StringComparison.OrdinalIgnoreCase)) Add("CGW");
    else if (norm.Equals("CGW", StringComparison.OrdinalIgnoreCase)) Add("GW");

    // AVAS <-> ESS
    if (norm.Equals("AVAS", StringComparison.OrdinalIgnoreCase)) Add("ESS");
    else if (norm.Equals("ESS", StringComparison.OrdinalIgnoreCase)) Add("AVAS");

    // MHU <-> HU / IVI / AVN
    if (norm.Equals("MHU", StringComparison.OrdinalIgnoreCase)) { Add("HU"); Add("IVI"); Add("AVN"); }
    else if (norm.Equals("HU", StringComparison.OrdinalIgnoreCase)) { Add("MHU"); }

    return aliases;
}

private string GetCleanEcuName(EcuDtcModel ecu)
{
    return Regex.Replace(ecu?.EcuDisplayName ?? "", @"[^\w\- ]", "").Trim();
}

