private DtcLibraryInfo GetDtcInfoFromLibraryOptimized(EcuDtcModel ecu, string dtcCode)
{
    string ecuName = GetCleanEcuName(ecu);
    string normalizedDtcCode = NormalizeDtcCodeText(dtcCode);
    var aliases = GetEcuAliases(ecuName);

    // 1. Kiểm tra cache trước (cho ECU name và các alias của nó)
    foreach (var alias in aliases)
    {
        DtcLibraryInfo cachedInfo;
        if (TryGetDtcInfoFromCache(alias, normalizedDtcCode, out cachedInfo))
        {
            if (IsUsefulDtcName(cachedInfo.Name))
                return cachedInfo;
        }
    }

    try
    {
        string currentProject = cbProjectList.SelectedItem?.ToString() ?? "";
        var filesToSearch = new System.Collections.Generic.List<Tuple<string, string, bool>>();

        // 2. File cấu hình ODXPath của xe hiện tại (ưu tiên số 1, không gán nhãn Refer)
        if (!string.IsNullOrEmpty(ecu.ODXPath))
        {
            string fullOdxPath = ResolveDtcLibraryPath(ecu.ODXPath);
            if (!string.IsNullOrEmpty(fullOdxPath))
                filesToSearch.Add(Tuple.Create(fullOdxPath, currentProject, false));
        }

        // 3. Quét các file json trong General/ID của các dòng xe khác tìm theo ECU name hoặc alias
        string idDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "General", "ID");
        if (Directory.Exists(idDir))
        {
            var jsonFiles = Directory.GetFiles(idDir, "*.json");
            foreach (var jsonFile in jsonFiles)
            {
                try
                {
                    string content = File.ReadAllText(jsonFile);
                    var config = JsonSerializer.Deserialize<ProjectConfig>(content);
                    if (config?.EcuList != null)
                    {
                        string sourceProject = !string.IsNullOrWhiteSpace(config.ProjectName)
                            ? config.ProjectName
                            : Path.GetFileNameWithoutExtension(jsonFile);

                        if (string.Equals(sourceProject, currentProject, StringComparison.OrdinalIgnoreCase))
                            continue;

                        foreach (var alias in aliases)
                        {
                            var matchEcu = config.EcuList.FirstOrDefault(x => string.Equals(x.ECUName, alias, StringComparison.OrdinalIgnoreCase) && !string.IsNullOrEmpty(x.ODXPath));
                            if (matchEcu != null)
                            {
                                string fullFallbackPath = ResolveDtcLibraryPath(matchEcu.ODXPath);
                                if (!string.IsNullOrEmpty(fullFallbackPath) && !filesToSearch.Any(x => string.Equals(x.Item1, fullFallbackPath, StringComparison.OrdinalIgnoreCase)))
                                    filesToSearch.Add(Tuple.Create(fullFallbackPath, sourceProject, true));
                            }
                        }
                    }
                }
                catch { }
            }
        }

        // 4. Quét fallback trong thư mục General/DTC nếu cần
        string dtcBaseDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "General", "DTC");
        if (Directory.Exists(dtcBaseDir))
        {
            var xlsxFiles = Directory.GetFiles(dtcBaseDir, "*.xlsx", SearchOption.AllDirectories);
            foreach (var xlsx in xlsxFiles)
            {
