private async void btnExportExcel_Click(object sender, RoutedEventArgs e)
{
    var L = LocalizationManager.Instance;

    if (_dtcRecords.Count == 0)
    {
        MessageBox.Show(L["dtc.noDataExport"], L["dtc.noticeTitle"], MessageBoxButton.OK, MessageBoxImage.Information);
        return;
    }

    var btn = sender as Button;
    string originalContent = btn != null ? btn.Content.ToString() : "";

    // Format tên file
    string vin = (txtVin.Text == "-" || string.IsNullOrEmpty(txtVin.Text) || txtVin.Text == L["dtc.reading"]) ? "UnknownVIN" : txtVin.Text;
    string proj = string.IsNullOrEmpty(cbProjectList.Text) ? "UnknownProject" : cbProjectList.Text;
    string dateStr = DateTime.Now.ToString("yyyyMMdd_HHmmss");
    string defaultFileName = $"DTC_{vin}_{proj}_{dateStr}.xlsx";

    Microsoft.Win32.SaveFileDialog saveFileDialog = new Microsoft.Win32.SaveFileDialog
    {
        FileName = defaultFileName,
        Filter = "Excel Workbook (*.xlsx)|*.xlsx",
        Title = L["dtc.saveDialogTitle"]
    };

    if (saveFileDialog.ShowDialog() == true)
    {
        if (btn != null)
        {
            btn.IsEnabled = false;
            btn.Content = L["dtc.exporting"];
        }

        try
        {
            // Lấy Status Mask từ Tag (0x09, 0xFF...) — không lấy Content để tránh chứa chữ "Real"
            string maskContent = "0xFF";
            if (cbStatusMask.SelectedItem is ComboBoxItem cbi && cbi.Tag != null)
                maskContent = cbi.Tag.ToString();

            byte maskByte = 0x09;
            try { maskByte = Convert.ToByte(maskContent.Replace("0x", ""), 16); } catch { }

            RefreshDtcNamesForExport();

            using (var workbook = new ClosedXML.Excel.XLWorkbook())
            {
                var ws = workbook.Worksheets.Add("Report");

                // Row 1 -> 4: Header Text
                ws.Cell(1, 1).Value = $"Time: {DateTime.Now.ToString("M/d/yyyy h:mm:ss tt")}";
                ws.Cell(2, 1).Value = $"Vehicle: {proj}";
                ws.Cell(3, 1).Value = $"VIN: {vin}";
                ws.Cell(4, 1).Value = $"Status Mask: {maskContent}";

                // Row 5: DTC Report (Spans A5:K5)
                var titleRange = ws.Range("A5:K5");
                titleRange.Merge().Value = "DTC Report";
                titleRange.Style.Fill.BackgroundColor = ClosedXML.Excel.XLColor.FromHtml("#B4C6E7"); // Light blue
                titleRange.Style.Font.Bold = true;
                titleRange.Style.Alignment.Horizontal = ClosedXML.Excel.XLAlignmentHorizontalValues.Center;
                titleRange.Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;

                // Row 6: Column Headers
                string[] headers = { "Node", "DTC Code", "DTC Name", "", "Status bytes", "Snapshot data", "", "", "", "", "Remark" };
                for (int i = 0; i < headers.Length; i++)
                {
                    if (!string.IsNullOrEmpty(headers[i]))
                    {
                        var cell = ws.Cell(6, i + 1);
                        cell.Value = headers[i];
                        cell.Style.Font.Bold = true;
                        cell.Style.Fill.BackgroundColor = ClosedXML.Excel.XLColor.FromHtml("#D9E1F2");
                        cell.Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;
                    }
                }

                // Merge header cells
                ws.Range("C6:D6").Merge();
                ws.Range("C6:D6").Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;
                ws.Range("F6:J6").Merge();
                ws.Range("F6:J6").Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;
                ws.Cell(6, 11).Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin; // K6

                int row = 7;
                var warningBg = ClosedXML.Excel.XLColor.FromHtml("#FFF2CC");
                int totalRecords = _dtcRecords.Count;
                int currentIdx = 0;

                foreach (var r in _dtcRecords)
                {
                    currentIdx++;

                    // ── Phân loại 3 trạng thái ──────────────────────────────
                    bool isNoResponse = (r.Dtc == "-" && r.StatusColor == "#DC2626");
                    bool isNoFault    = (r.Dtc == "-" && r.MoTa == L["dtc.noDtc"]);
                    bool isRealDtc    = (r.Dtc != "-");

                    if (btn != null && CanManager != null && CanManager.IsConnected && (isRealDtc || isNoFault))
                    {
                        btn.Content = $"{L["dtc.exporting"]} ({currentIdx}/{totalRecords})...";
                        await Task.Yield();
                    }

                    // Cột A: Node (Loại bỏ emoji)
                    string cleanNode = System.Text.RegularExpressions.Regex.Replace(r.Node ?? "", @"[^\w\- ]", "").Trim();
                    ws.Cell(row, 1).Value = cleanNode;
                    ws.Cell(row, 1).Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;

                    // Merge C-D và F-J trước (dùng chung cho cả 3 nhánh)
                    var nameRange = ws.Range(row, 3, row, 4);
                    nameRange.Merge();
                    nameRange.Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;
                    nameRange.Style.Alignment.WrapText = true;

                    var snapRange = ws.Range(row, 6, row, 10);
                    snapRange.Merge();
                    snapRange.Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;
                    snapRange.Style.Alignment.WrapText = true;
                    snapRange.Style.Alignment.Vertical = ClosedXML.Excel.XLAlignmentVerticalValues.Top;

                    if (isNoResponse)
                    {
                        // ── No Response: tô nền vàng, ghi "---" ──────────────
                        ws.Cell(row, 2).Value = "---";
                        nameRange.Value = "---";
                        ws.Cell(row, 5).Value = "---";
                        snapRange.Value = "NO RESPONSE";
                        ws.Cell(row, 11).Value = "No response";

                        // Tô nền vàng nhạt cho B → K
                        ws.Range(row, 2, row, 11).Style.Fill.BackgroundColor = warningBg;
                    }
                    else if (isNoFault)
                    {
                        // ── No Fault: No DTC, status zero bits ─
                        ws.Cell(row, 2).Value = "No DTC";
                        nameRange.Value = "";
                        ws.Cell(row, 5).Value = "0-0-0-0-0-0-0-0";
                        ws.Cell(row, 11).Value = "";

                        bool fetched = false;
                        if (CanManager != null && CanManager.IsConnected)
                        {
                            try
                            {
                                var targetEcu = _ecuCollection.FirstOrDefault(x => x.EcuDisplayName == r.Node);
                                if (targetEcu != null && targetEcu.TxId != 0)
                                {
                                    byte[] payload1902 = { 0x19, 0x02, maskByte };
                                    string txStr = BitConverter.ToString(payload1902).Replace("-", " ");
                                    CanManager.SendIsoTpAuto(targetEcu.TxId, payload1902);
                                    byte[] resp = await CanManager.ReceiveIsoTpUdsAsync(targetEcu.TxId, targetEcu.RxId, 1000);
                                    string rxStr = (resp != null && resp.Length > 0)
                                        ? BitConverter.ToString(resp).Replace("-", " ")
                                        : L["dtc.noResponse"];
                                    snapRange.Value = string.Format("{0}: {1}\n\n{2}: {3}", L["dtc.received"], rxStr, L["dtc.transmitted"], txStr);
                                    fetched = true;
                                }
                            }
                            catch { }
                        }

                        if (!fetched)
                        {
                            snapRange.Value = "No Fault (0 DTC)";
                        }
                    }
                    else if (isRealDtc)
                    {
                        // ── DTC thật: mã lỗi + bit string + snapshot ──────────
                        ws.Cell(row, 2).Value = r.Dtc;
                        nameRange.Value = r.MoTa;
                        ws.Cell(row, 5).Value = r.Status; // đã là "0-1-0-0-1-0-1-1"
                        ws.Cell(row, 11).Value = "";

                        if (!string.IsNullOrEmpty(r.SnapshotData))
                        {
                            snapRange.Value = r.SnapshotData;
                        }
                        else if (CanManager != null && CanManager.IsConnected)
                        {
                            try
                            {
                                var targetEcu = _ecuCollection.FirstOrDefault(x => x.EcuDisplayName == r.Node);
                                string[] rawBytes = (r.FullFrame ?? "").Split(' ');
                                if (rawBytes.Length >= 3 && targetEcu != null && targetEcu.TxId != 0)
                                {
                                    byte[] payload1904 = {
                                        0x19, 0x04,
                                        Convert.ToByte(rawBytes[0], 16),
                                        Convert.ToByte(rawBytes[1], 16),
                                        Convert.ToByte(rawBytes[2], 16),
                                        0xFF // Thử Record 0xFF trước
                                    };
                                    string txStr = BitConverter.ToString(payload1904).Replace("-", " ");
                                    CanManager.SendIsoTpAuto(targetEcu.TxId, payload1904);
                                    byte[] resp = await CanManager.ReceiveIsoTpUdsAsync(targetEcu.TxId, targetEcu.RxId, 1200);

                                    // Fallback Record 0x01 nếu ECU trả NRC 0x31 hoặc không có response
                                    if (resp == null || (resp.Length >= 3 && resp[0] == 0x7F && resp[1] == 0x19 && resp[2] == 0x31))
                                    {
                                        byte[] payloadFallback = {
                                            0x19, 0x04,
                                            Convert.ToByte(rawBytes[0], 16),
                                            Convert.ToByte(rawBytes[1], 16),
                                            Convert.ToByte(rawBytes[2], 16),
                                            0x01
                                        };
                                        txStr = BitConverter.ToString(payloadFallback).Replace("-", " ");
                                        CanManager.SendIsoTpAuto(targetEcu.TxId, payloadFallback);
                                        resp = await CanManager.ReceiveIsoTpUdsAsync(targetEcu.TxId, targetEcu.RxId, 1200);
                                    }

                                    string rxStr = (resp != null && resp.Length > 0)
                                        ? BitConverter.ToString(resp).Replace("-", " ")
                                        : L["dtc.noResponse"];

                                    string finalSnapshot = string.Format("{0}: {1}\n\n{2}: {3}", L["dtc.received"], rxStr, L["dtc.transmitted"], txStr);
                                    r.SnapshotData = finalSnapshot;
                                    snapRange.Value = finalSnapshot;
                                }
                                else if (!string.IsNullOrEmpty(r.FullFrame))
                                {
                                    snapRange.Value = string.Format(L["dtc.fullFrame1902"], r.FullFrame);
                                }
                            }
                            catch
                            {
                                if (!string.IsNullOrEmpty(r.FullFrame))
                                    snapRange.Value = string.Format(L["dtc.fullFrame1902"], r.FullFrame);
                            }
                        }
                        else if (!string.IsNullOrEmpty(r.FullFrame))
                        {
                            snapRange.Value = string.Format(L["dtc.fullFrame1902"], r.FullFrame);
                        }
                    }

                    // Border chung B, E, K
                    ws.Cell(row, 2).Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;
                    ws.Cell(row, 5).Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;
                    ws.Cell(row, 11).Style.Border.OutsideBorder = ClosedXML.Excel.XLBorderStyleValues.Thin;

                    row++;
                }

                // Định dạng độ rộng cột cho đẹp
                ws.Column(1).Width = 15; // Node
                ws.Column(2).Width = 15; // DTC Code
                ws.Column(3).Width = 25; // DTC Name (C)
                ws.Column(4).Width = 10; // DTC Name (D)
                ws.Column(5).Width = 15; // Status
                ws.Column(6).Width = 20; // Snapshot (F)
                ws.Column(7).Width = 15; // (G)
                ws.Column(8).Width = 15; // (H)
                ws.Column(9).Width = 15; // (I)
                ws.Column(10).Width = 15; // (J)
                ws.Column(11).Width = 20; // Remark

                workbook.SaveAs(saveFileDialog.FileName);
            }

            MessageBox.Show(L["dtc.exportSuccess"], L["dtc.noticeTitle"], MessageBoxButton.OK, MessageBoxImage.Information);
        }
        catch (Exception ex)
        {
            MessageBox.Show(string.Format(L["dtc.exportError"], ex.Message), L["dtc.errorTitle"], MessageBoxButton.OK, MessageBoxImage.Error);
        }
        finally
        {
            if (btn != null)
            {
                btn.IsEnabled = true;
                btn.Content = originalContent;
            }
        }
    }
}

