import openpyxl
import re

def normalize_header(value):
    text = (value or '').upper().replace('_', ' ').replace('-', ' ')
    return re.sub(r'\s+', ' ', text).strip()

def is_dtc_code_header(header):
    if not header or 'DTC' not in header: return False
    if any(k in header for k in ['NAME', 'DESCRIPTION', 'MEANING', 'DEFINITION', 'PRIORITY', 'LAMP']):
        return False
    return header == 'DTC' or 'DTC NUMBER' in header or 'DTC CODE' in header or 'FAULT CODE' in header or ' HEX' in header

def is_dtc_name_header(header):
    if not header: return False
    return 'DTC NAME' in header or header == 'DESCRIPTION' or 'FAULT DESCRIPTION' in header or header == 'NAME'

wb = openpyxl.load_workbook(r'TreeViews and Value Converters\bin\Debug\General\DTC\VF9NP\CVC.xlsx', data_only=True)
for sname in wb.sheetnames:
    ws = wb[sname]
    print('Testing sheet:', sname)
    dtcCols = []
    nameCol = -1
    headerRow = -1
    for r in range(1, min(ws.max_row, 20) + 1):
        for c in range(1, ws.max_column + 1):
            h = normalize_header(str(ws.cell(r, c).value or ''))
            if is_dtc_code_header(h) and c not in dtcCols:
                dtcCols.append(c)
                print(f'Found dtcCol {c}: [{h}]')
            if nameCol == -1 and is_dtc_name_header(h):
                nameCol = c
                print(f'Found nameCol {c}: [{h}]')
        if dtcCols and nameCol != -1:
            headerRow = r
            print(f'Header row detected: {headerRow}')
            break
    print(f'Result: headerRow={headerRow}, dtcCols={dtcCols}, nameCol={nameCol}')
"

