using System;
using System.IO;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using ClosedXML.Excel;

class Program {
    static void Main() {
        string baseDir = AppDomain.CurrentDomain.BaseDirectory;
        Console.WriteLine('BaseDir: ' + baseDir);
        string cvcPath = Path.Combine(baseDir, @'TreeViews and Value Converters\bin\Debug\General\DTC\VF9NP\CVC.xlsx');
        if (!File.Exists(cvcPath)) {
            cvcPath = Path.Combine(baseDir, @'General\DTC\VF9NP\CVC.xlsx');
        }
        Console.WriteLine('CVC exists: ' + File.Exists(cvcPath) + ' (' + cvcPath + ')');

        var dict = LoadDtcDictionaryFromFileOptimized(cvcPath);
        Console.WriteLine('Dict count: ' + dict.Count);

        string code = 'U1881-83';
        foreach (var key in GetDtcKeyCandidates(NormalizeDtcCodeText(code))) {
            Console.WriteLine('Candidate: [' + key + '] -> ' + (dict.ContainsKey(key) ? dict[key].Name : 'NOT FOUND'));
        }
    }

    static string NormalizeDtcCodeText(string value) {
        string text = Regex.Replace(value ?? '', @'\s+', '').ToUpperInvariant();
        if (text.StartsWith('0X')) text = text.Substring(2);
        return text.Replace('-', '');
    }

    static bool TryJ2012ToRawHex(string j2012, out string rawHex) {
        rawHex = null;
        if (string.IsNullOrWhiteSpace(j2012) || j2012.Length < 3) return false;
        char first = char.ToUpperInvariant(j2012[0]);
        int highDigit;
        switch (first) {
            case 'P': highDigit = 0; break;
            case 'C': highDigit = 4; break;
            case 'B': highDigit = 8; break;
            case 'U': highDigit = 12; break;
            default: return false;
        }
        int secondDigit;
        if (!int.TryParse(j2012.Substring(1, 1), System.Globalization.NumberStyles.HexNumber, null, out secondDigit) || secondDigit > 3)
            return false;
        byte b0 = (byte)((highDigit | secondDigit) & 0xFF);
        rawHex = b0.ToString('X2') + j2012.Substring(2);
        return true;
    }

    static List<string> GetDtcKeyCandidates(string dtcCode) {
        var candidates = new List<string>();
        void Add(string key) {
            if (!string.IsNullOrEmpty(key) && !candidates.Contains(key))
                candidates.Add(key);
        }
        string normalized = NormalizeDtcCodeText(dtcCode);
        Add(normalized);
        string rawHex;
        if (TryJ2012ToRawHex(normalized, out rawHex)) Add(rawHex);
        if (normalized.Length > 2) {
            string baseCode = normalized.Substring(0, normalized.Length - 2);
            Add(baseCode);
            Add(baseCode + '00');
            Add(baseCode + '-00');
        }
        if (!string.IsNullOrEmpty(rawHex) && rawHex.Length > 2) {
            string baseHex = rawHex.Substring(0, rawHex.Length - 2);
            Add(baseHex);
            Add(baseHex + '00');
        }
        return candidates;
    }

    static string NormalizeHeaderText(string value) {
        string text = (value ?? '').ToUpperInvariant().Replace('_', ' ').Replace('-', ' ');
        return Regex.Replace(text, @'\s+', ' ').Trim();
    }

    static bool IsDtcCodeHeader(string header) {
        if (string.IsNullOrWhiteSpace(header) || !header.Contains('DTC')) return false;
        if (header.Contains('NAME') || header.Contains('DESCRIPTION') || header.Contains('MEANING') || header.Contains('DEFINITION') || header.Contains('PRIORITY') || header.Contains('LAMP'))
            return false;
        return header == 'DTC' || header.Contains('DTC NUMBER') || header.Contains('DTC CODE') || header.Contains('FAULT CODE') || header.Contains(' HEX');
    }

    static bool IsDtcNameHeader(string header) {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Contains('DTC NAME') || header == 'DESCRIPTION' || header.Contains('FAULT DESCRIPTION') || header == 'NAME';
    }

    static void AddDtcDictionaryKey(Dictionary<string, DtcLibraryInfo> dict, string rawCode, DtcLibraryInfo info) {
        string code = NormalizeDtcCodeText(rawCode);
        if (string.IsNullOrEmpty(code)) return;
        foreach (var key in GetDtcKeyCandidates(code)) {
            if (!dict.ContainsKey(key)) dict[key] = info;
        }
    }

    static Dictionary<string, DtcLibraryInfo> LoadDtcDictionaryFromFileOptimized(string filePath) {
        var dict = new Dictionary<string, DtcLibraryInfo>();
        try {
            using (var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            using (var workbook = new XLWorkbook(fs)) {
                foreach (var ws in workbook.Worksheets) {
                    var lastRowUsed = ws.LastRowUsed();
                    var lastColUsed = ws.LastColumnUsed();
                    if (lastRowUsed == null || lastColUsed == null) continue;
                    var dtcCols = new List<int>();
                    int nameCol = -1, testCol = -1, actionCol = -1, headerRow = -1;
                    int lastRow = lastRowUsed.RowNumber();
                    int lastCol = lastColUsed.ColumnNumber();
                    for (int r = 1; r <= Math.Min(lastRow, 20); r++) {
                        for (int c = 1; c <= lastCol; c++) {
                            string h = NormalizeHeaderText(ws.Cell(r, c).GetString());
                            if (IsDtcCodeHeader(h) && !dtcCols.Contains(c)) dtcCols.Add(c);
                            if (nameCol == -1 && IsDtcNameHeader(h)) nameCol = c;
                            if (testCol == -1 && (h.Contains('TEST FAILED') || h.Contains('CONFIRMATION FAILURE') || h.Contains('REPAIRACTION'))) testCol = c;
                            if (actionCol == -1 && h.Contains('ECU FAILURE ACTION')) actionCol = c;
                        }
                        if (dtcCols.Count > 0 && nameCol != -1) {
                            headerRow = r;
                            break;
                        }
                    }
                    if (dtcCols.Count == 0 || nameCol == -1 || headerRow == -1) continue;
                    for (int r = headerRow + 1; r <= lastRow; r++) {
                        var info = new DtcLibraryInfo {
                            Name = ws.Cell(r, nameCol).GetString().Trim(),
                            TestCriteria = 'N/A',
                            EcuAction = 'N/A'
                        };
                        if (string.IsNullOrWhiteSpace(info.Name)) continue;
                        foreach (var dtcCol in dtcCols) {
                            var cell = ws.Cell(r, dtcCol);
                            string rawCode = cell.GetString();
                            if (string.IsNullOrWhiteSpace(rawCode) && !cell.IsEmpty()) rawCode = cell.Value.ToString();
                            if (!string.IsNullOrWhiteSpace(rawCode)) AddDtcDictionaryKey(dict, rawCode, info);
                        }
                    }
                }
            }
        } catch (Exception ex) { Console.WriteLine('Error: ' + ex); }
        return dict;
    }
}

class DtcLibraryInfo {
    public string Name { get; set; }
    public string TestCriteria { get; set; }
    public string EcuAction { get; set; }
}
