using System.Text.RegularExpressions;
using ClosedXML.Excel;

class Program {
    static void Main() {
        string path = @"TreeViews and Value Converters\bin\Debug\General\DTC\VF9NP\CVC.xlsx";
        Console.WriteLine("Testing path: " + path + ", Exists: " + File.Exists(path));

        var dict = new Dictionary<string, string>();
        try {
            using (var fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            using (var workbook = new XLWorkbook(fs)) {
                Console.WriteLine("Workbook opened successfully. Worksheets: " + workbook.Worksheets.Count);
                foreach (var ws in workbook.Worksheets) {
                    Console.WriteLine("Sheet: '" + ws.Name + "'");
                    var lastRowUsed = ws.LastRowUsed();
                    var lastColUsed = ws.LastColumnUsed();
                    Console.WriteLine("LastRow: " + (lastRowUsed != null ? lastRowUsed.RowNumber().ToString() : "null"));
                    Console.WriteLine("LastCol: " + (lastColUsed != null ? lastColUsed.ColumnNumber().ToString() : "null"));
                    if (lastRowUsed == null || lastColUsed == null) continue;

                    var dtcCols = new List<int>();
                    int nameCol = -1, testCol = -1, actionCol = -1, headerRow = -1;
                    int lastRow = lastRowUsed.RowNumber();
                    int lastCol = lastColUsed.ColumnNumber();

                    for (int r = 1; r <= Math.Min(lastRow, 20); r++) {
                        for (int c = 1; c <= lastCol; c++) {
                            string h = NormalizeHeaderText(ws.Cell(r, c).GetString());
                            if (IsDtcCodeHeader(h) && !dtcCols.Contains(c)) dtcCols.Add(c);
                            if (nameCol == -1 && IsDtcNameHeader(h)) nameCol = c;
                            if (testCol == -1 && (h.Contains("TEST FAILED") || h.Contains("CONFIRMATION FAILURE") || h.Contains("REPAIRACTION"))) testCol = c;
                            if (actionCol == -1 && h.Contains("ECU FAILURE ACTION")) actionCol = c;
                        }
                        if (dtcCols.Count > 0 && nameCol != -1) {
                            headerRow = r;
                            break;
                        }
                    }

                    Console.WriteLine("headerRow: " + headerRow + ", dtcCols: " + string.Join(",", dtcCols) + ", nameCol: " + nameCol);
                    if (dtcCols.Count == 0 || nameCol == -1 || headerRow == -1) continue;

                    int loadedRows = 0;
                    for (int r = headerRow + 1; r <= lastRow; r++) {
                        string name = ws.Cell(r, nameCol).GetString().Trim();
                        if (string.IsNullOrWhiteSpace(name)) continue;

                        foreach (var dtcCol in dtcCols) {
                            var cell = ws.Cell(r, dtcCol);
                            string rawCode = cell.GetString();
                            if (string.IsNullOrWhiteSpace(rawCode) && !cell.IsEmpty())
                                rawCode = cell.Value.ToString();

                            if (!string.IsNullOrWhiteSpace(rawCode)) {
                                string clean = rawCode.ToUpperInvariant().Replace("-", "").Replace(" ", "");
                                if (clean.StartsWith("0X")) clean = clean.Substring(2);
                                dict[clean] = name;
                                loadedRows++;
                            }
                        }
                    }
                    Console.WriteLine("Loaded keys from this sheet: " + loadedRows);
                }
            }
        } catch (Exception ex) {
            Console.WriteLine("EXCEPTION: " + ex);
        }

        Console.WriteLine("Total dict keys: " + dict.Count);
        string[] testKeys = { "U188183", "D88183", "U1881", "D881" };
        foreach (var k in testKeys) {
            Console.WriteLine("Key [" + k + "] -> " + (dict.ContainsKey(k) ? dict[k] : "NOT FOUND"));
        }
    }

    static string NormalizeHeaderText(string value) {
        string text = (value ?? "").ToUpperInvariant().Replace("_", " ").Replace("-", " ");
        return Regex.Replace(text, @"\s+", " ").Trim();
    }

    static bool IsDtcCodeHeader(string header) {
        if (string.IsNullOrWhiteSpace(header) || !header.Contains("DTC")) return false;
        if (header.Contains("NAME") || header.Contains("DESCRIPTION") || header.Contains("MEANING") || header.Contains("DEFINITION") || header.Contains("PRIORITY") || header.Contains("LAMP"))
            return false;
        return header == "DTC" || header.Contains("DTC NUMBER") || header.Contains("DTC CODE") || header.Contains("FAULT CODE") || header.Contains(" HEX");
    }

    static bool IsDtcNameHeader(string header) {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Contains("DTC NAME") || header == "DESCRIPTION" || header.Contains("FAULT DESCRIPTION") || header == "NAME";
    }
}
