import openpyxl, re, os, glob

def normalize_header(s):
    t = (s or '').upper().replace('_', ' ').replace('-', ' ')
    return re.sub(r'\s+', ' ', t).strip()

def is_dtc_code_header(h):
    if not h or 'DTC' not in h: return False
    if any(k in h for k in ['NAME', 'DESCRIPTION', 'MEANING', 'DEFINITION', 'PRIORITY', 'LAMP']): return False
    return h == 'DTC' or 'DTC NUMBER' in h or 'DTC CODE' in h or 'FAULT CODE' in h or ' HEX' in h

def is_dtc_name_header(h):
    if not h: return False
    return 'DTC NAME' in h or h == 'DESCRIPTION' or 'FAULT DESCRIPTION' in h or h == 'NAME'

def normalize_dtc_code_text(value):
    text = re.sub(r'\s+', '', value or '').upper()
    if text.startswith('0X'): text = text[2:]
    return text.replace('-', '')

def is_hex_text(value):
    return bool(value) and all((c in '0123456789ABCDEF') for c in value)

def try_j2012_to_raw_hex(dtc_code):
    text = normalize_dtc_code_text(dtc_code)
    if len(text) == 7 and text[0] in 'PCBU' and is_hex_text(text[1:]):
        letter_idx = 'PCBU'.index(text[0])
        d1 = int(text[1], 16) & 0x03
        d2 = int(text[2], 16) & 0x0F
        b1 = (letter_idx << 6) | (d1 << 4) | d2
        return f'{b1:02X}{text[3:7]}'
    if len(text) == 6 and is_hex_text(text):
        return text
    return None

def get_dtc_key_candidates(dtc_code):
    candidates = []
    def add(k):
        if k and k not in candidates: candidates.append(k)
    normalized = normalize_dtc_code_text(dtc_code)
    add(normalized)
    raw_hex = try_j2012_to_raw_hex(normalized)
    if raw_hex: add(raw_hex)
    if len(normalized) > 2:
        base_code = normalized[:-2]
        add(base_code)
        add(base_code + '00')
        add(base_code + '-00')
    if raw_hex and len(raw_hex) > 2:
        base_hex = raw_hex[:-2]
        add(base_hex)
        add(base_hex + '00')
    return candidates

def add_dtc_dictionary_key(d, raw_code, name):
    code = normalize_dtc_code_text(raw_code)
    if not code: return
    for key in get_dtc_key_candidates(code):
        if key not in d: d[key] = name
    if is_hex_text(code) and 0 < len(code) < 6:
        padded = code.zfill(6)
        for key in get_dtc_key_candidates(padded):
            if key not in d: d[key] = name

def load_file(filePath):
    dict_res = {}
    wb = openpyxl.load_workbook(filePath, data_only=True)
    for ws in wb.worksheets:
        lastRow = ws.max_row
        lastCol = ws.max_column
        dtcCols = []
        nameCol = -1
        headerRow = -1
        for r in range(1, min(lastRow + 1, 21)):
            for c in range(1, lastCol + 1):
                h = normalize_header(str(ws.cell(r, c).value or ''))
                if is_dtc_code_header(h) and c not in dtcCols: dtcCols.append(c)
                if nameCol == -1 and is_dtc_name_header(h): nameCol = c
            if dtcCols and nameCol != -1:
                headerRow = r
                break
        if not dtcCols or nameCol == -1 or headerRow == -1:
            continue
        for r in range(headerRow + 1, lastRow + 1):
            name_val = str(ws.cell(r, nameCol).value or '').strip()
            if not name_val or name_val.lower() == 'none': continue
            for dtcCol in dtcCols:
                raw_code = str(ws.cell(r, dtcCol).value or '').strip()
                if raw_code and raw_code.lower() != 'none':
                    add_dtc_dictionary_key(dict_res, raw_code, name_val)
    return dict_res

cvc_file = r"TreeViews and Value Converters\bin\Debug\General\DTC\VF9NP\CVC.xlsx"
cvc_dict = load_file(cvc_file)
print("CVC dict keys count:", len(cvc_dict))
for q in ["U1881-83", "U188183", "D88183"]:
    cands = get_dtc_key_candidates(q)
    print(f"Query {q} cands: {cands}")
    for c in cands:
        if c in cvc_dict:
            print(f"  FOUND {c} -> {cvc_dict[c]}")

