using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using ClosedXML.Excel;

class Program
{
    static string NormalizeHeaderText(string value)
    {
        string text = (value ?? "").ToUpperInvariant().Replace("_", " ").Replace("-", " ");
        return Regex.Replace(text, @"\s+", " ").Trim();
    }

    static bool IsDtcCodeHeader(string header)
    {
        if (string.IsNullOrWhiteSpace(header) || !header.Contains("DTC")) return false;
        if (header.Contains("NAME") || header.Contains("DESCRIPTION") || header.Contains("MEANING") || header.Contains("DEFINITION") || header.Contains("PRIORITY") || header.Contains("LAMP"))
            return false;

        return header == "DTC"
            || header.Contains("DTC NUMBER")
            || header.Contains("DTC CODE")
            || header.Contains("FAULT CODE")
            || header.Contains(" HEX");
    }

    static bool IsDtcNameHeader(string header)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        return header.Contains("DTC NAME")
            || header == "DESCRIPTION"
            || header.Contains("FAULT DESCRIPTION")
            || header == "NAME";
    }

    static string NormalizeDtcCodeText(string value)
    {
        string text = Regex.Replace(value ?? "", @"\s+", "").ToUpperInvariant();
        if (text.StartsWith("0X")) text = text.Substring(2);
        return text.Replace("-", "");
    }

    static bool IsHexText(string value)
    {
        if (string.IsNullOrEmpty(value)) return false;
        foreach (char ch in value)
        {
            bool isHex = (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'F');
            if (!isHex) return false;
        }
        return true;
    }

    static bool TryJ2012ToRawHex(string dtcCode, out string rawHex)
    {
        rawHex = "";
        string text = NormalizeDtcCodeText(dtcCode);

        if (text.Length == 7 && "PCBU".IndexOf(text[0]) >= 0 && IsHexText(text.Substring(1)))
        {
            int letterIndex = "PCBU".IndexOf(text[0]);
            int d1 = Convert.ToInt32(text.Substring(1, 1), 16) & 0x03;
            int d2 = Convert.ToInt32(text.Substring(2, 1), 16) & 0x0F;
            int b1 = (letterIndex << 6) | (d1 << 4) | d2;
            rawHex = $"{b1:X2}{text.Substring(3, 4)}";
            return true;
        }

        if (text.Length == 6 && IsHexText(text))
        {
            rawHex = text;
            return true;
        }

        return false;
    }

    static List<string> GetDtcKeyCandidates(string dtcCode)
    {
        var candidates = new List<string>();

        void Add(string key)
        {
            if (!string.IsNullOrEmpty(key) && !candidates.Contains(key))
                candidates.Add(key);
        }

        string normalized = NormalizeDtcCodeText(dtcCode);
        Add(normalized);

        string rawHex;
        if (TryJ2012ToRawHex(normalized, out rawHex))
            Add(rawHex);

        if (normalized.Length > 2)
        {
            string baseCode = normalized.Substring(0, normalized.Length - 2);
            Add(baseCode);
            Add(baseCode + "00");
            Add(baseCode + "-00");
        }

        if (!string.IsNullOrEmpty(rawHex) && rawHex.Length > 2)
        {
            string baseHex = rawHex.Substring(0, rawHex.Length - 2);
            Add(baseHex);
            Add(baseHex + "00");
        }

        return candidates;
    }

    static void AddDtcDictionaryKey(Dictionary<string, string> dict, string rawCode, string infoName)
    {
        string code = NormalizeDtcCodeText(rawCode);
        if (string.IsNullOrEmpty(code)) return;

        foreach (var key in GetDtcKeyCandidates(code))
        {
            if (!dict.ContainsKey(key)) dict[key] = infoName;
        }

        if (IsHexText(code) && code.Length > 0 && code.Length < 6)
        {
            string padded = code.PadLeft(6, '0');
            foreach (var key in GetDtcKeyCandidates(padded))
            {
                if (!dict.ContainsKey(key)) dict[key] = infoName;
            }
        }
    }

    static void Main()
    {
        string filePath = @"d:\Automotive dev\TOOL ĐỌC DTC DID EBUS\V1.5\Ebus_tool\TreeViews and Value Converters\bin\Debug\General\DTC\VF9NP\CVC.xlsx";
        Console.WriteLine("Testing file: " + filePath);
        Console.WriteLine("File exists: " + File.Exists(filePath));

        var dict = new Dictionary<string, string>();
        try
        {
            using (var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
            using (var workbook = new ClosedXML.Excel.XLWorkbook(fs))
            {
                Console.WriteLine("Worksheets count: " + workbook.Worksheets.Count);
                foreach (var ws in workbook.Worksheets)
                {
                    Console.WriteLine("WS: " + ws.Name);
                    var lastRowUsed = ws.LastRowUsed();
                    var lastColUsed = ws.LastColumnUsed();
                    if (lastRowUsed == null || lastColUsed == null)
                    {
                        Console.WriteLine("  lastRowUsed or lastColUsed is null!");
                        continue;
                    }

                    var dtcCols = new List<int>();
                    int nameCol = -1, testCol = -1, actionCol = -1, headerRow = -1;
                    int lastRow = lastRowUsed.RowNumber();
                    int lastCol = lastColUsed.ColumnNumber();
                    Console.WriteLine($"  lastRow={lastRow}, lastCol={lastCol}");

                    for (int r = 1; r <= Math.Min(lastRow, 20); r++)
                    {
                        for (int c = 1; c <= lastCol; c++)
                        {
                            string h = NormalizeHeaderText(ws.Cell(r, c).GetString());
                            if (IsDtcCodeHeader(h) && !dtcCols.Contains(c)) dtcCols.Add(c);
                            if (nameCol == -1 && IsDtcNameHeader(h)) nameCol = c;
                            if (testCol == -1 && (h.Contains("TEST FAILED") || h.Contains("CONFIRMATION FAILURE") || h.Contains("REPAIRACTION"))) testCol = c;
                            if (actionCol == -1 && h.Contains("ECU FAILURE ACTION")) actionCol = c;
                        }
                        if (dtcCols.Count > 0 && nameCol != -1)
                        {
                            headerRow = r;
                            break;
                        }
                    }

                    Console.WriteLine($"  headerRow={headerRow}, nameCol={nameCol}, dtcCols=[{string.Join(",", dtcCols)}]");
                    if (dtcCols.Count == 0 || nameCol == -1 || headerRow == -1)
                    {
                        Console.WriteLine("  SKIPPING SHEET because header not found!");
                        continue;
                    }

                    for (int r = headerRow + 1; r <= lastRow; r++)
                    {
                        string infoName = ws.Cell(r, nameCol).GetString().Trim();
                        if (string.IsNullOrWhiteSpace(infoName)) continue;

                        foreach (var dtcCol in dtcCols)
                        {
                            var cell = ws.Cell(r, dtcCol);
                            string rawCode = cell.GetString();
                            if (string.IsNullOrWhiteSpace(rawCode) && !cell.IsEmpty())
                                rawCode = cell.Value.ToString();

                            if (!string.IsNullOrWhiteSpace(rawCode))
                                AddDtcDictionaryKey(dict, rawCode, infoName);
                        }
                    }
                }
            }

            Console.WriteLine("Total keys added to dict: " + dict.Count);
            string testQuery = "U1881-83";
            var cands = GetDtcKeyCandidates(testQuery);
            Console.WriteLine("Candidates for " + testQuery + ": [" + string.Join(", ", cands) + "]");
            bool match = false;
            foreach (var k in cands)
            {
                if (dict.ContainsKey(k))
                {
                    Console.WriteLine($"MATCH! Key '{k}' => '{dict[k]}'");
                    match = true;
                    break;
                }
            }
            if (!match)
            {
                Console.WriteLine("NO MATCH FOUND!");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("EXCEPTION CAUGHT: " + ex.ToString());
        }
    }
}

