using System;
using System.IO;
using System.IO.Compression;
using System.Text.RegularExpressions;
using ClosedXML.Excel;

class Program
{
    static MemoryStream SanitizeWorkbookStream(string filePath)
    {
        var ms = new MemoryStream();
        using (var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
        {
            fs.CopyTo(ms);
        }
        ms.Position = 0;

        try
        {
            using (var archive = new ZipArchive(ms, ZipArchiveMode.Update, true))
            {
                var entry = archive.GetEntry("xl/workbook.xml");
                if (entry != null)
                {
                    string xml;
                    using (var reader = new StreamReader(entry.Open()))
                    {
                        xml = reader.ReadToEnd();
                    }

                    if (xml.Contains("<definedNames>") || xml.Contains("<definedNames "))
                    {
                        // Remove definedNames section completely
                        string sanitizedXml = Regex.Replace(xml, @"<definedNames[\s\S]*?</definedNames>", "", RegexOptions.IgnoreCase);
                        entry.Delete();
                        var newEntry = archive.CreateEntry("xl/workbook.xml");
                        using (var writer = new StreamWriter(newEntry.Open()))
                        {
                            writer.Write(sanitizedXml);
                        }
                        Console.WriteLine("Successfully stripped definedNames from xl/workbook.xml!");
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Sanitize exception: " + ex.Message);
        }

        ms.Position = 0;
        return ms;
    }

    static void Main()
    {
        string filePath = @"d:\Automotive dev\TOOL ĐỌC DTC DID EBUS\V1.5\Ebus_tool\TreeViews and Value Converters\bin\Debug\General\DTC\VF9NP\CVC.xlsx";
        Console.WriteLine("Testing with ZipArchive sanitization on: " + filePath);

        using (var ms = SanitizeWorkbookStream(filePath))
        using (var wb = new XLWorkbook(ms))
        {
            Console.WriteLine("ClosedXML SUCCESS! Worksheets count: " + wb.Worksheets.Count);
            var ws = wb.Worksheet(1);
            Console.WriteLine("Sheet name: " + ws.Name + ", Rows: " + ws.LastRowUsed().RowNumber());
            Console.WriteLine("Row 459: " + ws.Cell(459, 4).GetString() + " | " + ws.Cell(459, 5).GetString() + " | " + ws.Cell(459, 7).GetString());
        }
    }
}

