    _snapshotCts?.Cancel();
    _snapshotCts = new CancellationTokenSource();
    var snapToken = _snapshotCts.Token;
    try
    {
        await Task.Delay(150, snapToken);
    }
    catch (TaskCanceledException)
    {
        return;
    }

    if (_currentSelection != selected) return;

    try
    {
        var targetEcu = _ecuCollection.FirstOrDefault(x => x.EcuDisplayName == selected.Node);
        if (targetEcu != null && targetEcu.TxId != 0 && CanManager != null && CanManager.IsConnected)
        {
            // Lấy 3 byte DTC từ chuỗi FullFrame cũ (VD: "90 E0 04 2F" -> "90", "E0", "04")
            string[] rawBytes = (selected.FullFrame ?? "").Split(' ');
            if (rawBytes.Length >= 3)
            {
                byte[] payload1904 = {
                    0x19, 0x04,
                    Convert.ToByte(rawBytes[0], 16),
                    Convert.ToByte(rawBytes[1], 16),
                    Convert.ToByte(rawBytes[2], 16),
                    0xFF // Thử Record 0xFF trước
                };

                string txStr = BitConverter.ToString(payload1904).Replace("-", " ");
                txtDetailFullFrame.Text = string.Format(L["dtc.snapshotFormat"], txStr, L["dtc.waiting"]);

                CanManager.SendIsoTpAuto(targetEcu.TxId, payload1904);
                byte[] resp = await CanManager.ReceiveIsoTpUdsAsync(targetEcu.TxId, targetEcu.RxId, 1200);

                // Nếu user đã click sang dòng khác trong lúc chờ, bỏ qua kết quả này
                if (_currentSelection != selected || snapToken.IsCancellationRequested) return;

                // Fallback: nếu ECU trả NRC 0x31 (RequestOutOfRange) hoặc không trả lời với Record 0xFF, thử Record 0x01
                if (resp == null || (resp.Length >= 3 && resp[0] == 0x7F && resp[1] == 0x19 && resp[2] == 0x31))
                {
                    byte[] payloadFallback = {
                        0x19, 0x04,
                        Convert.ToByte(rawBytes[0], 16),
                        Convert.ToByte(rawBytes[1], 16),
                        Convert.ToByte(rawBytes[2], 16),
                        0x01 // Fallback Record 0x01
                    };
                    txStr = BitConverter.ToString(payloadFallback).Replace("-", " ");
                    CanManager.SendIsoTpAuto(targetEcu.TxId, payloadFallback);
                    resp = await CanManager.ReceiveIsoTpUdsAsync(targetEcu.TxId, targetEcu.RxId, 1200);
                    if (_currentSelection != selected || snapToken.IsCancellationRequested) return;
                }

                string rxStr = (resp != null && resp.Length > 0)
                    ? BitConverter.ToString(resp).Replace("-", " ")
                    : L["dtc.noResponse"];

                string finalSnapshot = string.Format("{0}: {1}\n\n{2}: {3}", L["dtc.received"], rxStr, L["dtc.transmitted"], txStr);
                selected.SnapshotData = finalSnapshot;
                txtDetailFullFrame.Text = finalSnapshot;
            }
            else
            {
                txtDetailFullFrame.Text = string.Format(L["dtc.fullFrame1902"], selected.FullFrame);
            }
        }
        else
        {
            txtDetailFullFrame.Text = string.Format(L["dtc.fullFrame1902"], selected.FullFrame);
        }
    }
    catch
    {
        if (_currentSelection == selected)
            txtDetailFullFrame.Text = L["dtc.snapshotError"];
    }
}

