private static MemoryStream OpenSanitizedExcelStream(string filePath)
{
    var ms = new MemoryStream();
    using (var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite))
    {
        fs.CopyTo(ms);
    }
    ms.Position = 0;

    try
    {
        using (var archive = new System.IO.Compression.ZipArchive(ms, System.IO.Compression.ZipArchiveMode.Update, true))
        {
            var entry = archive.GetEntry("xl/workbook.xml");
            if (entry != null)
            {
                string xml;
                using (var reader = new StreamReader(entry.Open()))
                {
                    xml = reader.ReadToEnd();
                }

                if (xml.IndexOf("<definedNames", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    string sanitizedXml = Regex.Replace(xml, @"<definedNames[\s\S]*?</definedNames>", "", RegexOptions.IgnoreCase);
                    entry.Delete();
                    var newEntry = archive.CreateEntry("xl/workbook.xml");
                    using (var writer = new StreamWriter(newEntry.Open()))
                    {
                        writer.Write(sanitizedXml);
                    }
                }
            }
        }
    }
    catch (Exception ex)
    {
        Debug.WriteLine("[DTC] OpenSanitizedExcelStream warning: " + ex.Message);
    }

    ms.Position = 0;
    return ms;
}

private System.Collections.Generic.Dictionary<string, DtcLibraryInfo> LoadDtcDictionaryFromFileOptimized(string filePath)
{
    var dict = new System.Collections.Generic.Dictionary<string, DtcLibraryInfo>();
    try
    {
        using (var ms = OpenSanitizedExcelStream(filePath))
        using (var workbook = new ClosedXML.Excel.XLWorkbook(ms))
        {
            foreach (var ws in workbook.Worksheets)
            {
                var lastRowUsed = ws.LastRowUsed();
                var lastColUsed = ws.LastColumnUsed();
                if (lastRowUsed == null || lastColUsed == null) continue;

                var dtcCols = new System.Collections.Generic.List<int>();
                int nameCol = -1, testCol = -1, actionCol = -1, headerRow = -1;
                int lastRow = lastRowUsed.RowNumber();
                int lastCol = lastColUsed.ColumnNumber();

                for (int r = 1; r <= Math.Min(lastRow, 20); r++)
                {
                    for (int c = 1; c <= lastCol; c++)
                    {
                        string h = NormalizeHeaderText(ws.Cell(r, c).GetString());
                        if (IsDtcCodeHeader(h) && !dtcCols.Contains(c)) dtcCols.Add(c);
                        if (nameCol == -1 && IsDtcNameHeader(h)) nameCol = c;
                        if (testCol == -1 && (h.Contains("TEST FAILED") || h.Contains("CONFIRMATION FAILURE") || h.Contains("REPAIRACTION"))) testCol = c;
                        if (actionCol == -1 && h.Contains("ECU FAILURE ACTION")) actionCol = c;
                    }
                    if (dtcCols.Count > 0 && nameCol != -1)
                    {
                        headerRow = r;
                        break;
                    }
                }

                if (dtcCols.Count == 0 || nameCol == -1 || headerRow == -1)
                    continue;

                for (int r = headerRow + 1; r <= lastRow; r++)
                {
                    var info = new DtcLibraryInfo
                    {
                        Name = ws.Cell(r, nameCol).GetString().Trim(),
                        TestCriteria = testCol != -1 ? ws.Cell(r, testCol).GetString().Trim() : LocalizationManager.Instance["dtc.na"],
                        EcuAction = actionCol != -1 ? ws.Cell(r, actionCol).GetString().Trim() : LocalizationManager.Instance["dtc.na"]
                    };

                    if (string.IsNullOrWhiteSpace(info.Name)) continue;

                    foreach (var dtcCol in dtcCols)
                    {
                        var cell = ws.Cell(r, dtcCol);
                        string rawCode = cell.GetString();
                        if (string.IsNullOrWhiteSpace(rawCode) && !cell.IsEmpty())
                            rawCode = cell.Value.ToString();

                        if (!string.IsNullOrWhiteSpace(rawCode))
                            AddDtcDictionaryKey(dict, rawCode, info);
                    }
                }
            }
        }
    }
    catch (Exception ex)
    {
        Debug.WriteLine("[DTC] LoadDtcDictionaryFromFileOptimized error: " + ex.Message);
    }
    return dict;
}

private System.Collections.Generic.Dictionary<string, DtcLibraryInfo> LoadDtcDictionaryFromFile(string filePath)
{
    var dict = new System.Collections.Generic.Dictionary<string, DtcLibraryInfo>();
    try
    {
        using (var ms = OpenSanitizedExcelStream(filePath))
        using (var workbook = new ClosedXML.Excel.XLWorkbook(ms))
        {
            var ws = workbook.Worksheets.First();
            var dtcCols = new System.Collections.Generic.List<int>();
            int nameCol = -1, testCol = -1, actionCol = -1;
            int lastRow = ws.LastRowUsed().RowNumber();
            int lastCol = ws.LastColumnUsed().ColumnNumber();

            for (int r = 1; r <= Math.Min(lastRow, 10); r++)
            {
                for (int c = 1; c <= lastCol; c++)
                {
                    string h = ws.Cell(r, c).GetString().Trim().ToUpper();
                    if (h.Contains("DTC NUMBER") || h == "DTC") dtcCols.Add(c);
                    if (nameCol == -1 && (h.Contains("DTC NAME") || h == "DESCRIPTION")) nameCol = c;
                    if (testCol == -1 && (h.Contains("TEST FAILED") || h.Contains("CONFIRMATION FAILURE") || h.Contains("REPAIRACTION"))) testCol = c;
                    if (actionCol == -1 && h.Contains("ECU FAILURE ACTION")) actionCol = c;
                }
                if (dtcCols.Count > 0 && nameCol != -1) break;
            }

            if (dtcCols.Count > 0 && nameCol != -1)
            {
                for (int r = 2; r <= lastRow; r++)
                {
                    var info = new DtcLibraryInfo
                    {
                        Name = ws.Cell(r, nameCol).GetString().Trim(),
                        TestCriteria = testCol != -1 ? ws.Cell(r, testCol).GetString().Trim() : LocalizationManager.Instance["dtc.na"],
                        EcuAction = actionCol != -1 ? ws.Cell(r, actionCol).GetString().Trim() : LocalizationManager.Instance["dtc.na"]
                    };

                    foreach (var dtcCol in dtcCols)
                    {
                        string rawCode = ws.Cell(r, dtcCol).GetString();
                        if (!string.IsNullOrEmpty(rawCode))
                        {
                            // Bóc tách triệt để khoảng trắng ẩn, xuống dòng (\n), \r, \t từ file Excel
                            string code = System.Text.RegularExpressions.Regex.Replace(rawCode, @"\s+", "").ToUpper();

                            if (code.Length > 0)
                            {
                                if (!dict.ContainsKey(code)) dict[code] = info;
                                string clean = code.Replace("-", "");
                                if (!dict.ContainsKey(clean)) dict[clean] = info;
                            }
                        }
                    }
                }
            }
        }
    }
    catch (Exception ex)
    {
        Debug.WriteLine("[DTC] LoadDtcDictionaryFromFile error: " + ex.Message);
    }
    return dict;
}

