using System;
using System.IO;
using System.Collections.Generic;

namespace TestRunner {
    class Program {
        static void Main(string[] args) {
            try {
                string cvcPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, @"General\DTC\VF9NP\CVC.xlsx");
                Console.WriteLine("CVC Path: " + cvcPath + " (Exists: " + File.Exists(cvcPath) + ")");
                var dtcType = typeof(TreeViews_and_Value_Converters.DTC);
                var sanitizeMethod = dtcType.GetMethod("OpenSanitizedExcelStream", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public);
                using (var ms = (MemoryStream)sanitizeMethod.Invoke(null, new object[] { cvcPath })) {
                    Console.WriteLine("Sanitized stream length: " + ms.Length);
                    using (var workbook = new ClosedXML.Excel.XLWorkbook(ms)) {
                        Console.WriteLine("Workbook worksheets count: " + workbook.Worksheets.Count);
                        foreach (var ws in workbook.Worksheets) {
                            Console.WriteLine("WS: " + ws.Name + ", LastRow: " + (ws.LastRowUsed() != null ? ws.LastRowUsed().RowNumber().ToString() : "null"));
                        }
                    }
                }
            } catch (Exception ex) {
                Console.WriteLine("ERROR: " + ex.ToString());
            }
        }
    }
}
