namespace TestRunner {
    class Program {
        static void Main(string[] args) {
            string cvcPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, @"General\DTC\VF9NP\CVC.xlsx");
            var dtcType = typeof(TreeViews_and_Value_Converters.DTC);
            var dummyInstance = FormatterServices.GetUninitializedObject(dtcType);
            var method = dtcType.GetMethod("LoadDtcDictionaryFromFileOptimized", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public);
            var dict = (Dictionary<string, TreeViews_and_Value_Converters.DtcLibraryInfo>)method.Invoke(dummyInstance, new object[] { cvcPath });

            var getCandidatesMethod = dtcType.GetMethod("GetDtcKeyCandidates", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public);

            string userReport = @"C:\Users\Hnam\Downloads\DTC_RLLV1WHW0TH781483_VF9NP_20261005_174001.xlsx";
            if (!File.Exists(userReport)) {
                Console.WriteLine("User report file not found on path, skipping user report scan.");
                return;
            }

            using (var wb = new ClosedXML.Excel.XLWorkbook(userReport)) {
                var ws = wb.Worksheet("DTC_Details") ?? wb.Worksheet(1);
                int lastRow = ws.LastRowUsed().RowNumber();
                Console.WriteLine("Scanning user report " + ws.Name + " (" + lastRow + " rows)...");
                int cvcCount = 0, resolvedCount = 0;
                for (int r = 2; r <= lastRow; r++) {
                    string ecu = ws.Cell(r, 1).GetString().Trim();
                    if (!ecu.Equals("CVC", StringComparison.OrdinalIgnoreCase)) continue;
                    cvcCount++;
                    string dtcCode = ws.Cell(r, 2).GetString().Trim();
                    string oldDesc = ws.Cell(r, 3).GetString().Trim();

                    var candidates = (List<string>)getCandidatesMethod.Invoke(dummyInstance, new object[] { dtcCode });
                    TreeViews_and_Value_Converters.DtcLibraryInfo foundInfo = null;
                    foreach (var c in candidates) {
                        if (dict.TryGetValue(c, out foundInfo)) break;
                    }

                    if (foundInfo != null && !string.IsNullOrWhiteSpace(foundInfo.Name)) {
                        resolvedCount++;
                        Console.WriteLine("Row " + r + ": [" + dtcCode + "] Old='" + oldDesc + "' => Resolved='" + foundInfo.Name + "'");
                    } else {
                        Console.WriteLine("Row " + r + ": [" + dtcCode + "] Old='" + oldDesc + "' => STILL NOT FOUND");
                    }
                }
                Console.WriteLine("Summary: CVC DTCs in user file: " + cvcCount + ", Resolved: " + resolvedCount);
            }
        }
    }
}
