private static string NormalizeSnapshotOrder(string snapshot)
{
    if (string.IsNullOrWhiteSpace(snapshot)) return snapshot;
    var L = LocalizationManager.Instance;
    string[] recKeywords = new string[] { L["dtc.received"] + ":", "Received:", "已接收：", "已接收:", "수신됨:", "تم الاستقبال:" };
    string[] transKeywords = new string[] { L["dtc.transmitted"] + ":", "Transmitted:", "已发送：", "已发送:", "전송됨:", "تم الإرسال:" };

    int recIdx = -1;
    int recKeywordLen = 0;
    foreach (var k in recKeywords)
    {
        int idx = snapshot.IndexOf(k, StringComparison.OrdinalIgnoreCase);
        if (idx >= 0 && (recIdx < 0 || idx < recIdx))
        {
            recIdx = idx;
            recKeywordLen = k.Length;
        }
    }

    int transIdx = -1;
    foreach (var k in transKeywords)
    {
        int idx = snapshot.IndexOf(k, StringComparison.OrdinalIgnoreCase);
        if (idx >= 0 && (transIdx < 0 || idx < transIdx))
        {
            transIdx = idx;
        }
    }

    if (recIdx >= 0 && transIdx >= 0 && recIdx < transIdx)
    {
        string recPart = snapshot.Substring(recIdx, transIdx - recIdx).Trim();
        string transPart = snapshot.Substring(transIdx).Trim();
        return transPart + "\n\n" + recPart;
    }
    return snapshot;
}

