227:                         foreach (var frame in txToRxFrames)
228:                         {
229:                             if (token.IsCancellationRequested) break;
230:                             ProcessTxToRxFrame(frame);
231:                         }
232:                     }
233: 
234:                     if (rxToTxFrames.Count == 0 && txToRxFrames.Count == 0)
235:                     {
236:                         Thread.Sleep(1);
237:                     }
238:                 }
239:                 catch (OperationCanceledException) { break; }
240:                 catch (Exception ex)
241:                 {
242:                     System.Diagnostics.Debug.WriteLine($"[MitmEngine] Error: {ex.Message}");
243:                     Thread.Sleep(10);
244:                 }
245:             }
