// ═════════════════════════════════════════════════════════════════
//  PHASE 5.3: OVERRIDE → ENGINE INJECT
// ═════════════════════════════════════════════════════════════════

/// <summary>
/// Theo dõi thay đổi Override và PhysicalValue từ bảng Signal Value Setup.
/// Cập nhật bảng Override trong Engine nhưng KHÔNG tự động chuyển Message sang Inject.
/// Hành động truyền Inject do người dùng điều khiển độc quyền qua Quick Action (Send Once, Cyclic).
/// </summary>
private void OnSignalPropertyChanged(object sender, System.ComponentModel.PropertyChangedEventArgs e)
{
    if (!(sender is SignalItemModel sigModel)) return;
    if (sigModel.DbcSignalRef == null) return;

    // Chỉ xử lý khi user thay đổi Override hoặc PhysicalValue
    if (e.PropertyName != nameof(SignalItemModel.Override) &&
        e.PropertyName != nameof(SignalItemModel.PhysicalValue)) return;

    // Xác định message đang chọn
    if (!(TxDataGrid.SelectedItem is TxMessageModel selectedTx)) return;
    if (selectedTx.DbcMessageRef == null) return;

    uint canId = (uint)selectedTx.DbcMessageRef.CanId;
    string signalName = sigModel.DbcSignalRef.Name;

    // Cập nhật Override Table trong Engine
    _mitmEngine?.SetSignalOverride(canId, signalName, sigModel.PhysicalValue, sigModel.Override);

    // Event mode: chỉ tự động gửi frame khi giá trị PhysicalValue thay đổi (không gửi khi chỉ vừa mới tick Override)
    if (e.PropertyName == nameof(SignalItemModel.PhysicalValue) && sigModel.Override && selectedTx.SendType == "Event")
    {
        _mitmEngine?.OnSignalValueChanged(canId);
    }

    // [WORKFLOW] Đồng bộ checkbox Override cấp message để hiển thị trực quan trên danh sách TX
    bool anySignalOverride = _currentSignals.Any(s => s.Override);
    selectedTx.Override = anySignalOverride;

    // KHÔNG tự động chuyển selectedTx.Mode = GatewayMode.Inject ở đây!
    // Mode Inject chỉ được kích hoạt khi người dùng nhấn nút thao tác gửi trong Quick Action (Send Once / Cyclic).
    // Nếu người dùng bỏ tích toàn bộ signal, đảm bảo đưa về PassThrough nếu trước đó đang Inject.
    if (!anySignalOverride && selectedTx.Mode == GatewayMode.Inject)
    {
        selectedTx.Mode = GatewayMode.PassThrough;
        _mitmEngine?.UpdateTxList(_txMessages);
    }

    // Cập nhật trạng thái các nút Quick Action (Send Once, Send All Once...)
    UpdateQuickActionState();

    System.Diagnostics.Debug.WriteLine(
        $"[Override] {signalName} | Override={sigModel.Override} | Value={sigModel.PhysicalValue:F2} | Mode={selectedTx.Mode}");
}

