/// <summary>
/// Tạo hiệu ứng nhấp nháy thị giác tức thì (feedback pulse) khi nhấn nút Quick Action.
/// </summary>
private void TriggerButtonPulse(Button btn)
{
    if (btn == null) return;
    try
    {
        var anim = new System.Windows.Media.Animation.DoubleAnimation
        {
            From = 0.4,
            To = 1.0,
            Duration = TimeSpan.FromMilliseconds(200)
        };
        btn.BeginAnimation(UIElement.OpacityProperty, anim);
    }
    catch { }
}

