private async void BtnSendAllOnce_Click(object sender, RoutedEventArgs e)
{
    if (_mitmEngine == null) return;
    TriggerButtonPulse(BtnSendAllOnce);

    // Hủy chuỗi cũ nếu có
    _sequenceCts?.Cancel();
    _sequenceCts = new CancellationTokenSource();
    var token = _sequenceCts.Token;

    var tasks = new List<Task>();
    int msgCount = 0;

    foreach (var tx in _txMessages)
    {
        if (!tx.Enable || tx.DbcMessageRef == null) continue;
        msgCount++;

        uint canId = (uint)tx.DbcMessageRef.CanId;
        string sendType = tx.SendType;

        // Chuyển Mode sang Inject nếu có Override, giữ nguyên nếu không
        bool hasOverride = false;
        foreach (var sig in tx.DbcMessageRef.Signals)
        {
            if (_mitmEngine.HasOverride(canId, sig.Name))
            {
                hasOverride = true;
                break;
            }
        }

        if (hasOverride && tx.Mode != GatewayMode.Inject)
        {
            tx.Mode = GatewayMode.Inject;
            tx.Enable = true;
        }

        if (sendType == "Cyclic")
        {
            int totalSends = (tx.RepeatCount == 0) ? int.MaxValue : tx.RepeatCount;
            tasks.Add(ExecuteSingleStepAsync(tx, canId, tx.StartDelayMs, tx.CycleTime, totalSends, token, sendType, suppressCleanup: true));
        }
        else if (sendType == "One-Shot")
        {
            tasks.Add(ExecuteOneShotOnceAsync(tx, canId, token));
        }
        else // Event
        {
            tasks.Add(Task.Run(() =>
            {
                if (hasOverride)
                {
                    foreach (var sig in tx.DbcMessageRef.Signals)
                    {
                        if (_mitmEngine.HasOverride(canId, sig.Name))
                        {
                            double val = _mitmEngine.GetOverrideValue(canId, sig.Name);
                            _mitmEngine.SetSignalOverride(canId, sig.Name, val, true);
                        }
                    }
                }
                _mitmEngine.SendOnce(canId);
            }, token));
        }
    }

    _mitmEngine?.UpdateTxList(_txMessages);
    AddEventLog($"SEND ALL ONCE | {msgCount} messages | Cyclic/One-Shot/Event theo cấu hình");

    try
    {
        await Task.WhenAll(tasks);
        Application.Current.Dispatcher.Invoke(() =>
        {
            ResetAllOverrides();
            AddEventLog("SEND ALL ONCE — Hoàn thành tất cả");
        });
    }
    catch (TaskCanceledException)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            AddEventLog("SEND ALL ONCE — Đã hủy bởi STOP ALL");
        });
    }
}

/// <summary>
/// One-Shot cho SEND ALL ONCE: gửi đúng 1 frame với override sau start delay.
/// </summary>
private async Task ExecuteOneShotOnceAsync(TxMessageModel tx, uint canId, CancellationToken token)
{
    try
    {
        int delayMs = tx.StartDelayMs;
        if (delayMs > 0)
            await Task.Delay(delayMs, token);

        // Gửi 1 frame
        _mitmEngine.SendOnce(canId);

        Application.Current.Dispatcher.Invoke(() =>
        {
            StatsTimer_Tick(null, null);
            AddEventLog($"SEND ALL | One-Shot | {tx.MessageName} | Gửi 1 frame thành công");
        });
    }
    catch (TaskCanceledException)
    {
        // Bị STOP ALL hủy
        throw;
    }
}

private void BtnStopAll_Click(object sender, RoutedEventArgs e)
{
    TriggerButtonPulse(BtnStopAllCyclic);

    // Hủy chuỗi đang chạy (nếu có)
    _sequenceCts?.Cancel();

    // [WORKFLOW] Nút 4 được bấm -> Reset bỏ tích tất cả override, tắt Inject
    ResetAllOverrides();

    AddEventLog("STOP ALL CYCLIC — Overrides cleared, gateway still RUNNING");
}

private void BtnClearCounter_Click(object sender, RoutedEventArgs e)
{
    TriggerButtonPulse(BtnClearCounter);
    _mitmEngine?.ResetCounters();
    TxtMessagesSent.Text = "0";
    TxtRxCount.Text = "0";
    TxtInjectedCount.Text = "0";
    TxtElapsed.Text = "00:00:00";
    TxtLatency.Text = "0 µs";
    AddEventLog("CLEAR COUNTER — Reset counters");
}

