/// <summary>
/// One-Shot cho SEND ALL ONCE: gửi đúng 1 frame với override sau start delay,
/// sau đó tắt override và trả lại PassThrough. Không chạy vô tận như SEND ONCE đơn lẻ.
/// </summary>
private async Task ExecuteOneShotOnceAsync(TxMessageModel tx, uint canId, CancellationToken token)
{
    try
    {
        int delayMs = tx.StartDelayMs;
        if (delayMs > 0)
            await Task.Delay(delayMs, token);

        // Snapshot override signals
        var overridesToApply = new Dictionary<string, double>();
        foreach (var sig in tx.DbcMessageRef.Signals)
        {
            if (_mitmEngine.HasOverride(canId, sig.Name))
            {
                overridesToApply[sig.Name] = _mitmEngine.GetOverrideValue(canId, sig.Name);
            }
        }

        Application.Current.Dispatcher.Invoke(() =>
        {
            AddEventLog($"SEND ALL | One-Shot | {tx.MessageName} | Gửi 1 frame");
        });

        // Bật override
        foreach (var kvp in overridesToApply)
            _mitmEngine.SetSignalOverride(canId, kvp.Key, kvp.Value, true);

        // Gửi 1 frame
        _mitmEngine.SendOnce(canId);

        // Tắt override
        foreach (var kvp in overridesToApply)
            _mitmEngine.SetSignalOverride(canId, kvp.Key, 0, false);

        _mitmEngine.SendOnce(canId); // Gửi frame sạch để reset

        Application.Current.Dispatcher.Invoke(() =>
        {
            AddEventLog($"SEND ALL | One-Shot | {tx.MessageName} | Hoàn thành");
        });
    }
    catch (TaskCanceledException)
    {
        // Bị STOP ALL hủy
        throw;
    }
}

