private async void BtnSendOnce_Click(object sender, RoutedEventArgs e)
{
    if (_mitmEngine == null) return;
    if (TxDataGrid.SelectedItem is TxMessageModel selectedTx && selectedTx.DbcMessageRef != null)
    {
        TriggerButtonPulse(BtnSendOnce);
        uint canId = (uint)selectedTx.DbcMessageRef.CanId;

        // Dừng chuỗi cũ nếu có
        _sequenceCts?.Cancel();
        _sequenceCts = new CancellationTokenSource();
        var token = _sequenceCts.Token;

        string sendType = selectedTx.SendType;
        int startDelay = selectedTx.StartDelayMs;
        int cycleTime = selectedTx.CycleTime;
        int repeatCount = selectedTx.RepeatCount;

        // Ghi event log
        var overridden = _currentSignals.Where(s => s.Override).Select(s => s.SignalName).ToList();
        string signalList = overridden.Count > 0 ? string.Join(", ", overridden) : "none";
        AddEventLog($"SEQUENCE START | {sendType} | {selectedTx.MessageName} | [{signalList}]");

        // Bật Inject Mode cho message đang chọn
        selectedTx.Mode = GatewayMode.Inject;
        selectedTx.Enable = true;
        _mitmEngine?.UpdateTxList(_txMessages);

        if (sendType == "One-Shot")
        {
            await ExecuteOneShotAsync(selectedTx, canId, startDelay, token);
        }
        else if (sendType == "Event")
        {
            await ExecuteEventAsync(selectedTx, canId, startDelay, token);
        }
        else // Cyclic
        {
            int totalSends = (repeatCount == 0) ? int.MaxValue : repeatCount;
            await ExecuteCyclicSequenceAsync(selectedTx, canId, startDelay, cycleTime, totalSends, token, isBatch: false);
        }
    }
    else
    {
        var L = LocalizationManager.Instance;
        MessageBox.Show(L["sim.selectMsgInTxList"], L["sim.selectMsgInTxListTitle"], MessageBoxButton.OK, MessageBoxImage.Information);
    }
}

/// <summary>
/// One-Shot: Khóa lưới giá trị, bơm đè liên tục trong suốt thời gian cho tới khi nhấn STOP ALL CYCLIC.
/// </summary>
private async Task ExecuteOneShotAsync(TxMessageModel tx, uint canId, int delayMs, CancellationToken token)
{
    try
    {
        if (delayMs > 0)
        {
            await Task.Delay(delayMs, token);
        }

        Application.Current.Dispatcher.Invoke(() =>
        {
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = false; // Khóa lưới giá trị
            AddEventLog($"ONE-SHOT INJECT ACTIVE | {tx.MessageName} (Running continuously until STOP...)");
        });

        // Chờ vô tận cho đến khi bị hủy bởi STOP ALL CYCLIC
        await Task.Delay(-1, token);
    }
    catch (TaskCanceledException)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            tx.Mode = GatewayMode.PassThrough;
            _mitmEngine?.UpdateTxList(_txMessages);
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true;
            AddEventLog($"ONE-SHOT STOPPED | {tx.MessageName}");
        });
    }
    catch (Exception ex)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            tx.Mode = GatewayMode.PassThrough;
            _mitmEngine?.UpdateTxList(_txMessages);
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true;
            AddEventLog($"ONE-SHOT ERROR | {tx.MessageName} | {ex.Message}");
        });
    }
}

/// <summary>
/// Event: Mở lưới giá trị, bơm đè liên tục và cho phép người dùng Live Tuning đổi giá trị trực tiếp cho đến khi STOP.
/// </summary>
private async Task ExecuteEventAsync(TxMessageModel tx, uint canId, int delayMs, CancellationToken token)
{
    try
    {
        if (delayMs > 0)
        {
            await Task.Delay(delayMs, token);
        }

        Application.Current.Dispatcher.Invoke(() =>
        {
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true; // Mở lưới giá trị cho Live Tuning
            _mitmEngine?.SendOnce(canId); // Bắn frame đầu tiên xác lập trạng thái
            AddEventLog($"EVENT INJECT ACTIVE | {tx.MessageName} (Live Tuning enabled until STOP...)");
        });

        // Chờ vô tận cho đến khi bị hủy bởi STOP ALL CYCLIC
        await Task.Delay(-1, token);
    }
    catch (TaskCanceledException)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            tx.Mode = GatewayMode.PassThrough;
            _mitmEngine?.UpdateTxList(_txMessages);
            AddEventLog($"EVENT STOPPED | {tx.MessageName}");
        });
    }
    catch (Exception ex)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            tx.Mode = GatewayMode.PassThrough;
            _mitmEngine?.UpdateTxList(_txMessages);
            AddEventLog($"EVENT ERROR | {tx.MessageName} | {ex.Message}");
        });
    }
}

/// <summary>
/// Cyclic: Phát theo chu kỳ setup như delay, số lần inject (Active Time) và thời gian nghỉ (Gap Time).
/// </summary>
private async Task ExecuteCyclicSequenceAsync(TxMessageModel tx, uint canId, int delayMs, int cycleMs, int totalSends, CancellationToken token, bool isBatch = false)
{
    var L = LocalizationManager.Instance;
    try
    {
        if (delayMs > 0)
        {
            await Task.Delay(delayMs, token);
        }

        Application.Current.Dispatcher.Invoke(() =>
        {
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = false; // Khóa lưới giá trị trong chuỗi
        });

        for (int i = 0; i < totalSends; i++)
        {
            token.ThrowIfCancellationRequested();

            // Pha 1: Bật Inject (Active Time)
            Application.Current.Dispatcher.Invoke(() =>
            {
                tx.Mode = GatewayMode.Inject;
                _mitmEngine?.UpdateTxList(_txMessages);
                string countDisplay = (totalSends == int.MaxValue) ? "∞" : totalSends.ToString();
                AddEventLog(string.Format(L["sim.injectLog"], tx.MessageName, i + 1, countDisplay));
            });

            if (cycleMs > 0)
            {
                await Task.Delay(cycleMs, token);
            }

            // Pha 2: Tạm ngưng về PassThrough (Gap Time)
            if (i < totalSends - 1 && tx.GapTimeMs > 0)
            {
                Application.Current.Dispatcher.Invoke(() =>
                {
                    tx.Mode = GatewayMode.PassThrough;
                    _mitmEngine?.UpdateTxList(_txMessages);
                });

                await Task.Delay(tx.GapTimeMs, token);
            }
        }

        if (!token.IsCancellationRequested)
        {
            Application.Current.Dispatcher.Invoke(() =>
            {
                tx.Mode = GatewayMode.PassThrough;
                _mitmEngine?.UpdateTxList(_txMessages);
                if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true;

                if (!isBatch)
                {
                    MessageBox.Show(string.Format(L["sim.oneShotComplete"], "Cyclic", tx.MessageName, totalSends),
                                    L["sim.oneShotCompleteTitle"], MessageBoxButton.OK, MessageBoxImage.Information);
                }
                else
                {
                    AddEventLog($"CYCLIC DONE | {tx.MessageName} | {totalSends} lần hoàn thành");
                }
            });
        }
    }
    catch (TaskCanceledException)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            tx.Mode = GatewayMode.PassThrough;
            _mitmEngine?.UpdateTxList(_txMessages);
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true;
            AddEventLog($"CYCLIC CANCELED | {tx.MessageName}");
        });
    }
    catch (Exception ex)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            tx.Mode = GatewayMode.PassThrough;
            _mitmEngine?.UpdateTxList(_txMessages);
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true;
            var L2 = LocalizationManager.Instance;
            MessageBox.Show(string.Format(L2["sim.sequenceError"], ex.Message));
        });
    }
}

private void ResetAllOverrides()
{
    foreach (var tx in _txMessages)
    {
        tx.Override = false;
        tx.Mode = GatewayMode.PassThrough;
    }

    foreach (var sig in _currentSignals)
    {
        sig.PropertyChanged -= OnSignalPropertyChanged;
        sig.Override = false;
        sig.PropertyChanged += OnSignalPropertyChanged;
    }

    _mitmEngine?.ClearAllOverrides();
    _mitmEngine?.UpdateTxList(_txMessages);
    UpdateQuickActionState();

    if (SignalValueGrid != null)
    {
        SignalValueGrid.IsEnabled = true;
    }
}

private async void BtnSendAllOnce_Click(object sender, RoutedEventArgs e)
{
    if (_mitmEngine == null) return;
    TriggerButtonPulse(BtnSendAllOnce);

    // Hủy chuỗi cũ nếu có
    _sequenceCts?.Cancel();
    _sequenceCts = new CancellationTokenSource();
    var token = _sequenceCts.Token;

    var tasks = new List<Task>();
    int msgCount = 0;

    foreach (var tx in _txMessages)
    {
        if (!tx.Enable || tx.DbcMessageRef == null) continue;
        msgCount++;

        uint canId = (uint)tx.DbcMessageRef.CanId;
        string sendType = tx.SendType;

        // Kiểm tra xem message có signal nào được override không
        bool hasOverride = false;
        if (tx.DbcMessageRef.Signals != null)
        {
            foreach (var sig in tx.DbcMessageRef.Signals)
            {
                if (_mitmEngine.HasOverride(canId, sig.Name))
                {
                    hasOverride = true;
                    break;
                }
            }
        }

        if (hasOverride)
        {
            tx.Mode = GatewayMode.Inject;
            tx.Enable = true;

            if (sendType == "One-Shot")
            {
                tasks.Add(ExecuteOneShotAsync(tx, canId, tx.StartDelayMs, token));
            }
            else if (sendType == "Event")
            {
                tasks.Add(ExecuteEventAsync(tx, canId, tx.StartDelayMs, token));
            }
            else // Cyclic
            {
                int totalSends = (tx.RepeatCount == 0) ? int.MaxValue : tx.RepeatCount;
                tasks.Add(ExecuteCyclicSequenceAsync(tx, canId, tx.StartDelayMs, tx.CycleTime, totalSends, token, isBatch: true));
            }
        }
    }

    _mitmEngine?.UpdateTxList(_txMessages);
    AddEventLog($"SEND ALL ONCE | {msgCount} messages | One-Shot/Event/Cyclic started");

    try
    {
        await Task.WhenAll(tasks);
        Application.Current.Dispatcher.Invoke(() =>
        {
            ResetAllOverrides();
            AddEventLog("SEND ALL ONCE — Hoàn thành tất cả");
        });
    }
    catch (TaskCanceledException)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            AddEventLog("SEND ALL ONCE — Đã hủy bởi STOP ALL");
        });
    }
}

private void BtnStopAll_Click(object sender, RoutedEventArgs e)
{
    TriggerButtonPulse(BtnStopAllCyclic);

    // Hủy chuỗi đang chạy (nếu có)
    _sequenceCts?.Cancel();

    // Mở khóa lưới giá trị ngay lập tức
    if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true;

    // Khôi phục tất cả message về PassThrough
    foreach (var tx in _txMessages)
    {
        tx.Mode = GatewayMode.PassThrough;
    }
    _mitmEngine?.UpdateTxList(_txMessages);

    AddEventLog("STOP ALL CYCLIC — All injections stopped, restored to Pass-Through");
}

