                {
                    await Task.Delay(startDelay, token);
                }

                // Gửi đúng 1 frame với các giá trị override tín hiệu đã thiết lập (Mode vẫn giữ PassThrough)
                _mitmEngine.SendOnce(canId);
                StatsTimer_Tick(null, null);
                AddEventLog($"ONE-SHOT SENT | {selectedTx.MessageName} (ID: 0x{canId:X3}) | Gửi 1 frame thành công");
            }
            catch (TaskCanceledException)
            {
                AddEventLog($"ONE-SHOT CANCELED | {selectedTx.MessageName}");
            }
        }
        else if (sendType == "Cyclic")
        {
            // Chuyển Mode sang Inject và tự động Enable để GatewayLoop thực hiện can thiệp tuần hoàn
            if (selectedTx.Mode != GatewayMode.Inject || !selectedTx.Enable)
            {
                selectedTx.Mode = GatewayMode.Inject;
                selectedTx.Enable = true;
                _mitmEngine?.UpdateTxList(_txMessages);
            }

            int totalSends = (repeatCount == 0) ? int.MaxValue : repeatCount;
            await ExecuteSingleStepAsync(selectedTx, canId, startDelay, cycleTime, totalSends, token, sendType);
        }
        else // Event hoặc chưa chọn
        {
            // Chế độ Event gửi thủ công ngay lập tức 1 frame
            _mitmEngine.SendOnce(canId);
            StatsTimer_Tick(null, null);
            AddEventLog($"EVENT SENT | {selectedTx.MessageName} (ID: 0x{canId:X3})");
