}

private async Task ExecuteSingleStepAsync(TxMessageModel tx, uint canId, int delayMs, int cycleMs, int totalSends, CancellationToken token, string typeName, bool suppressCleanup = false)
{
    var L = LocalizationManager.Instance;
    try
    {
        if (delayMs > 0)
        {
            await Task.Delay(delayMs, token);
        }

        // Snapshot các signal đang được tích Override trên UI để dùng cho chuỗi này
        var overridesToApply = new Dictionary<string, double>();
        foreach (var sig in tx.DbcMessageRef.Signals)
        {
            if (_mitmEngine.HasOverride(canId, sig.Name))
            {
                overridesToApply[sig.Name] = _mitmEngine.GetOverrideValue(canId, sig.Name);
            }
        }

        if (typeName == "One-Shot")
        {
            // Gửi đúng 1 frame
            _mitmEngine.SendOnce(canId);
            Application.Current.Dispatcher.Invoke(() =>
            {
                StatsTimer_Tick(null, null);
                AddEventLog($"ONE-SHOT SENT | {tx.MessageName} (ID: 0x{canId:X3}) | Gửi 1 frame thành công");
            });
            return;
        }

        for (int i = 0; i < totalSends; i++)
        {
            token.ThrowIfCancellationRequested();

            // Update UI log
            Application.Current.Dispatcher.Invoke(() =>
            {
                string countDisplay = (totalSends == int.MaxValue) ? "∞" : totalSends.ToString();
                AddEventLog(string.Format(L["sim.injectLog"], tx.MessageName, i + 1, countDisplay));
            });

            // 1. BẬT OVERRIDE (Dùng GatewayLoop tự động inject)
            foreach (var kvp in overridesToApply)
            {
                _mitmEngine.SetSignalOverride(canId, kvp.Key, kvp.Value, true);
            }

            // 2. DUY TRÌ (Active Time)
            if (cycleMs > 0)
            {
                await Task.Delay(cycleMs, token);
            }

            // 3. TẮT OVERRIDE (Về PassThrough hoặc Fault=0)
            foreach (var kvp in overridesToApply)
            {
                // Reset về 0 và tắt override để ECU thật tự phát hoặc Gateway pass-through sạch
                _mitmEngine.SetSignalOverride(canId, kvp.Key, 0, false);
            }
            _mitmEngine.SendOnce(canId); // Gửi 1 frame sạch để reset trạng thái ECU ngay lập tức

            // 4. THỜI GIAN NGHỈ (Gap Time)
            if (i < totalSends - 1 && tx.GapTimeMs > 0)
            {
                await Task.Delay(tx.GapTimeMs, token);
            }
        }

        if (!token.IsCancellationRequested && !suppressCleanup)
        {
            // Hoàn thành sequence — đưa Mode về PassThrough
            Application.Current.Dispatcher.Invoke(() =>
            {
                tx.Mode = GatewayMode.PassThrough;
                _mitmEngine?.UpdateTxList(_txMessages);
                ResetAllOverrides();
                MessageBox.Show(string.Format(L["sim.oneShotComplete"], typeName, tx.MessageName, totalSends),
                                L["sim.oneShotCompleteTitle"], MessageBoxButton.OK, MessageBoxImage.Information);
            });
        }
        else if (!token.IsCancellationRequested && suppressCleanup)
        {
            // SEND ALL ONCE: đưa Mode về PassThrough
            Application.Current.Dispatcher.Invoke(() =>
            {
                tx.Mode = GatewayMode.PassThrough;
                _mitmEngine?.UpdateTxList(_txMessages);
                AddEventLog($"CYCLIC DONE | {tx.MessageName} | {totalSends} lần hoàn thành");
            });
        }
    }
    catch (TaskCanceledException)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            tx.Mode = GatewayMode.PassThrough;
            _mitmEngine?.UpdateTxList(_txMessages);
            if (SignalValueGrid != null) SignalValueGrid.IsEnabled = true;
            AddEventLog($"SEQUENCE CANCELED | {tx.MessageName}");
        });
    }
    catch (Exception ex)
    {
        Application.Current.Dispatcher.Invoke(() =>
        {
            var L2 = LocalizationManager.Instance;
            MessageBox.Show(string.Format(L2["sim.sequenceError"], ex.Message));
        });
    }
}





private void ResetAllOverrides()
{
    foreach (var tx in _txMessages)
    {
        tx.Override = false;
        tx.Mode = GatewayMode.PassThrough;
    }

    foreach (var sig in _currentSignals)
    {
        sig.PropertyChanged -= OnSignalPropertyChanged;
        sig.Override = false;
        sig.PropertyChanged += OnSignalPropertyChanged;
    }

    _mitmEngine?.ClearAllOverrides();
    _mitmEngine?.UpdateTxList(_txMessages);
    UpdateQuickActionState();

    if (SignalValueGrid != null)
    {
        SignalValueGrid.IsEnabled = true;
    }
}

