        public SelectMessageWindow(DbcDocument document, IReadOnlyList<DbcMessage>? alreadyAddedMessages = null)
        {
            InitializeComponent();
            ArgumentNullException.ThrowIfNull(document);

            var alreadyAddedIds = new HashSet<(uint, bool)>(
