            if (TxtSearchHint == null) return;
            string key = (TglSearchBySignal?.IsChecked == true)
                ? "Loc_SelMsg_SearchHint_WithSignals"
                : "Loc_SelMsg_SearchHint";

            if (TryFindResource(key) is string hintText && !string.IsNullOrEmpty(hintText))
            {
                TxtSearchHint.Text = hintText;
            }
        }

        private void TglSearchBySignal_Click(object sender, RoutedEventArgs e)
        {
            UpdateSearchHint();
            ApplyFilter();
        }

        private void TxtSearch_TextChanged(object sender, TextChangedEventArgs e)
        {
            ApplyFilter();
        }

        private void ApplyFilter()
        {
            string query = TxtSearch.Text.Trim();
            bool searchBySignal = TglSearchBySignal?.IsChecked == true;
            _filteredMessages.Clear();

            if (string.IsNullOrWhiteSpace(query))
            {
                foreach (var m in _allMessages)
                {
                    m.MatchedSignalsHint = string.Empty;
                    _filteredMessages.Add(m);
                }
                return;
            }

            foreach (var m in _allMessages)
            {
                bool matchesMsg = m.Name.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                                  m.FormattedId.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                                  m.Transmitter.Contains(query, StringComparison.OrdinalIgnoreCase);

                string matchedSig = string.Empty;
                bool matchesSignal = false;

                if (searchBySignal)
                {
                    var matchingSignals = m.SignalNames
                        .Where(s => s.Contains(query, StringComparison.OrdinalIgnoreCase))
                        .Take(3)
                        .ToList();

                    if (matchingSignals.Count > 0)
                    {
                        matchesSignal = true;
                        matchedSig = string.Join(", ", matchingSignals);
                    }
                }

                if (matchesMsg || matchesSignal)
                {
                    m.MatchedSignalsHint = matchedSig;
                    _filteredMessages.Add(m);
                }
            }
        }

        private void BtnSelectAll_Click(object sender, RoutedEventArgs e)
        {
            foreach (var message in _filteredMessages)
            {
                message.IsSelected = true;
            }
        }

        private void BtnDeselectAll_Click(object sender, RoutedEventArgs e)
        {
            foreach (var message in _filteredMessages)
            {
                message.IsSelected = false;
            }
        }

        private void BtnAdd_Click(object sender, RoutedEventArgs e)
        {
            SelectedMessages = _allMessages
                .Where(m => m.IsSelected)
                .Select(m => m.Message)
                .ToList();

            DialogResult = true;
            Close();
        }

        private void BtnCancel_Click(object sender, RoutedEventArgs e)
        {
            DialogResult = false;
            Close();
        }
    }
}
